package com.example.payupayments.payu_payments_demo;
/*
Below are the sample values for key, salt and environment
// These values are for testing purposes only and should not be used in production
private static final String KEY = "PRiQvJ";
private static final String SALT = "mGHSxpD2iBVywParGQrGBlaXjnwkGJMQ";
private static final String ENVIRONMENT = "sandbox";
*/
/*
 PayU API code for initiating payment, verify, refund
 Use proper packages for HTTP and crypto/hash as per your language!
 Key, Salt and Environment must be configured.
*/
/*external dependencies to be included in this project are as follows:
 *java-json.jar */

import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TimeZone;
import java.util.logging.Logger;
import org.json.JSONObject;
import java.awt.Desktop;
import java.net.URI;

import java.io.OutputStream;

public class PayU {

    // Logger
    private static final Logger logger = Logger.getLogger(PayU.class.getName());
    public static void main(String[] args) {
        // Insert your key, salt, and environment in the below variables
        /*
         *To get your own key and salt values, login to payu.in and create a new merchant account
         *Here is the documentation link for the same:
            *Access test key and salt as per the document: https://docs.payu.in/docs/generate-test-merchant-key-and-salt
            *Access production key and salt as per the document: https://docs.payu.in/docs/generate-merchant-key-and-salt-on-payu-dashboard
            *Registering for a new merchant account is easy and takes less than 5 minutes.
            *You can also use the test key and salt provided in the documentation for testing purposes.
            *The test key and salt are not valid for production use.
            * API Documentation for this integration is available here: https://docs.payu.in/v2/docs
        */
        final String key = "$KEY$"; // Replace with your actual merchant key
        final String salt = "$SALT$"; // Replace with your actual merchant salt
        final String environment = "$ENVIRONMENT$"; // Replace with "sandbox" or "prod"

        try {
            logger.info("Starting the payment process...");

            // Replace the dummy values with your actual payment values
            JSONObject data = new JSONObject();
            data.put("currency", "INR"); // Mandatory, this integration is only for INR
            data.put("accountId", key); // Mandatory, your merchant key
            data.put("txnId", "test_" + (int) (Math.random() * 10000)); // Mandatory and must be unique for reconciliation
            logger.info("Transaction ID generated: " + data.get("txnId"));

            JSONObject order = new JSONObject();
            order.put("productInfo", "$PRODUCT_INFO$"); // Mandatory, brief description of the product
            JSONObject paymentChargeSpecification = new JSONObject();
            paymentChargeSpecification.put("price", $PRICE$); // Mandatory, amount to be charged
            order.put("paymentChargeSpecification", paymentChargeSpecification);
            data.put("order", order);
            logger.info("Order details created: " + order.toString());

            //callback actions, used for redirection after payment
            JSONObject callBackActions = new JSONObject();
            callBackActions.put("successAction", "$SUCCESS_URL$"); // Mandatory, success URL replace with your actual URL
            callBackActions.put("failureAction", "$FAILURE_URL$"); // Mandatory, failure URL replace with your actual URL
            data.put("callBackActions", callBackActions);
            logger.info("Callback actions created: " + callBackActions.toString());

            JSONObject billingDetails = new JSONObject();
            billingDetails.put("firstName", "$FIRST_NAME$"); // Mandatory, first name of the customer
            billingDetails.put("phone", "$PHONE$"); // Mandatory, phone number of the customer
            billingDetails.put("lastName", ""); // Optional, last name of the customer
            billingDetails.put("address1", ""); // Optional, address line 1 of the customer
            billingDetails.put("address2", ""); // Optional, address line 2 of the customer
            billingDetails.put("city", ""); // Optional, city of the customer
            billingDetails.put("state", ""); // Optional, state of the customer
            billingDetails.put("country", ""); // Optional, country of the customer
            billingDetails.put("zipCode", ""); // Optional, zip code of the customer
            data.put("billingDetails", billingDetails);
            logger.info("Billing details created: " + billingDetails.toString());

            JSONObject additionalInfo = new JSONObject();
            additionalInfo.put("txnFlow", "nonseamless"); // Mandatory for non-seamless flow
            data.put("additionalInfo", additionalInfo);
            logger.info("Additional info added: " + additionalInfo.toString());

            logger.info("Final JSON payload to send: " + data.toString());
            logger.info("Initiating payment request...");

            String payuResponse = initiatePayment(key, salt, environment, data);
            logger.info("Payment response received: " + payuResponse);

            // Parse the response and handle accordingly
            JSONObject responseJson = new JSONObject(payuResponse);
            String status = responseJson.getString("status");
            if ("PENDING".equalsIgnoreCase(status)) {
                // Open the checkout URL in the browser, to complete the payment, you can use your own method to open the URL
                String checkoutUrl = responseJson.getJSONObject("result").getString("checkoutUrl");
                if (Desktop.isDesktopSupported() && Desktop.getDesktop().isSupported(Desktop.Action.BROWSE)) {
                    Desktop.getDesktop().browse(new URI(checkoutUrl));
                    logger.info("Browser opened with URL: " + checkoutUrl);
                } else {
                    logger.severe("Desktop browser support is not available. Please open this URL manually: " + checkoutUrl);
                }
            } else if ("FAILURE".equalsIgnoreCase(status)) {
                // Display failure reason
                JSONObject result = responseJson.getJSONObject("result");
                String failureReason = result.has("message") ? result.getString("message") : result.optString("msg", "Unknown failure reason");
                logger.severe("Payment failed. Reason: " + failureReason);
            } else {
                logger.warning("Unhandled status: " + status);
            }
        } catch (Exception e) {
            logger.severe("An error occurred during the payment process: " + e.getMessage());
        }
    }


    public static String initiatePayment(String key, String salt, String environment, JSONObject data) throws Exception {
        String paymentURL;

        if (environment.equals("sandbox")) {
            paymentURL = "https://apitest.payu.in/v2/payments"; // Sandbox URL for Payu payment initiation
        } else if (environment.equals("prod")) {
            paymentURL = "https://api.payu.in/v2/payments"; // Production URL for Payu payment initiation
        } else {
            logger.info("Invalid Environment passed: " + environment);
            throw new IllegalArgumentException("Invalid Environment passed. Expected values \"sandbox\" or \"prod\" but received: " + environment);
        }
        logger.info("Using payment URL: " + paymentURL);

        // Generate the date and hash for the authorization header
        String date = getFormattedDate();
        logger.info("Generated date: " + date);

        if (!data.has("accountId")) {
            data.put("accountId", key);
        }

        String hashString = data.toString() + "|" + date + "|" + salt;
        String hash = generateSHA512Hash(hashString);
        logger.info("Generated hash: " + hash);

        String authorizationHeader = "hmac username=\"" + key + "\", algorithm=\"sha512\", headers=\"date\", signature=\"" + hash + "\"";
        logger.info("Authorization header created: " + authorizationHeader);

        HttpURLConnection conn = (HttpURLConnection) new URL(paymentURL).openConnection();
        conn.setDoOutput(true);
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setRequestProperty("Authorization", authorizationHeader);
        conn.setRequestProperty("Date", date);

        logger.info("Setting up HTTP connection...");
        logger.info("Posting data to URL: " + paymentURL);
        logger.info("Raw JSON body being posted: " + data.toString());

        try (OutputStream os = conn.getOutputStream()) {
            os.write(data.toString().getBytes(StandardCharsets.UTF_8));
        }

        int responseCode = conn.getResponseCode();
        logger.info("HTTP Response Code: " + responseCode);

        if (responseCode == 200) {
            java.util.Scanner s = new java.util.Scanner(conn.getInputStream()).useDelimiter("\n");
            String response = s.hasNext() ? s.next() : "";
            logger.info("HTTP Response Body: " + response);
            return response;
        } else {
            logger.info("HTTP Request failed with status code: " + responseCode);
            throw new Exception("HTTP Request failed with status code: " + responseCode);
        }
    }


    // Generate SHA-512 hash
    // This method generates a SHA-512 hash of the input string
    private static String generateSHA512Hash(String data) throws Exception {
        logger.info("Generating SHA-512 hash...");
        MessageDigest digest = MessageDigest.getInstance("SHA-512");
        byte[] hash = digest.digest(data.getBytes(StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        String hashOutput = sb.toString();
        logger.info("Generated SHA-512 hash: " + hashOutput);
        return hashOutput;
    }

    // Get formatted date
    // This method returns the current date formatted as "EEE, dd MMM yyyy HH:mm:ss 'GMT'"
    public static String getFormattedDate() {
        SimpleDateFormat dateFormat = new SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss 'GMT'");
        dateFormat.setTimeZone(TimeZone.getTimeZone("GMT"));
        return dateFormat.format(new Date());
    }
}
$END$

/*
 PayU API code for initiating verify payment
 Key, Salt and Environment must be configured.
 Below is the code for verifying payment, 
 here is the API documentation link for the same: https://docs.payu.in/reference/verify_payment_api
*/

//Since the below code is a complete standalone java program, you may require to set up accordingly into your existing project
/* Uncomment the below imports if you are using this code in a standalone java program
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
*/

//classname for verifying payment
public class PayUVerifyPayment {

    // Insert your key, salt, and environment in the below variables
        /*
         *To get your own key and salt values, login to payu.in and create a new merchant account
         *Here is the documentation link for the same:
            *Access test key and salt as per the document: https://docs.payu.in/docs/generate-test-merchant-key-and-salt
            *Access production key and salt as per the document: https://docs.payu.in/docs/generate-merchant-key-and-salt-on-payu-dashboard
            *Registering for a new merchant account is easy and takes less than 5 minutes.
            *You can also use the test key and salt provided in the documentation for testing purposes.
            *The test key and salt are not valid for production use.
            * API Documentation for this integration is available here: https://docs.payu.in/reference/verify_payment_api
        */
    private static final String KEY = "$KEY$";
    private static final String SALT = "$SALT$";
    private static final String ENVIRONMENT = "$ENVIRONMENT$";

    public static void main(String[] args) {
        try {
            // Replace the txnid with your unique transaction ID, for which you want to verify the payment
            // This should be the same txnid used during the payment initiation
            String txnid = "$TXNID$";
            String response = verifyPayment(KEY, SALT, ENVIRONMENT, txnid); // Call the verifyPayment method
            // Print the response from the server
            System.out.println("Response from PayU Verify payment:");
            System.out.println(response);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * API Documentation for this integration is available here: https://docs.payu.in/reference/verify_payment_api
     * This method verifies the payment status for a given transaction ID.
     *
     * @param key This is the merchant key provided by PayU.
     * @param salt This is the merchant salt provided by PayU.
     * @param environment select the environment to use, either "sandbox" or "prod".
     * @param txnid put the transaction ID for which you want to verify the payment.
     * @return The response from the PayU server.
     */
    public static String verifyPayment(String key, String salt, String environment, String txnid) throws Exception {
        String apiURLV1;

        // Determine the API URL based on the environment entered
        if ("sandbox".equals(environment)) {
            apiURLV1 = "https://test.payu.in/merchant/postservice.php?form=2";
        } else if ("prod".equals(environment)) {
            apiURLV1 = "https://info.payu.in/merchant/postservice.php?form=2";
        } else {
            throw new IllegalArgumentException(
                "Invalid Environment passed. Expected values \"sandbox\" or \"prod\" but received: " + environment
            );
        }

        // This validates if the txnid is passed correctly or not
        // The txnid is mandatory for verifying the payment
        // It should be the same txnid used during the payment initiation
        if (txnid == null || txnid.isEmpty()) {
            throw new IllegalArgumentException("txnid is missing");
        }

        String command = "verify_payment"; // static value for verify payment

        // Create the hash for the request, this uses the key, command, txnid and salt passed in the method call
        String hashString = key + "|" + command + "|" + txnid + "|" + salt;
        String hash = generateSHA512HashAPI(hashString);

        // Prepare the form data
        String formBody = "key=" + encodeURIComponent(key) +
                          "&command=" + encodeURIComponent(command) +
                          "&var1=" + encodeURIComponent(txnid) +
                          "&hash=" + encodeURIComponent(hash);

        // Send POST request
        HttpURLConnection conn = (HttpURLConnection) new URL(apiURLV1).openConnection();
        conn.setDoOutput(true);
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded"); // This is the content type for form data

        // Write form data in the request body
        try (OutputStream os = conn.getOutputStream()) {
            os.write(formBody.getBytes(StandardCharsets.UTF_8));
        }

        // Read and return the response
        if (conn.getResponseCode() == 200) {
            java.util.Scanner s = new java.util.Scanner(conn.getInputStream()).useDelimiter("\n");
            return s.hasNext() ? s.next() : "";
        } else {
            throw new Exception("HTTP Request failed with status code: " + conn.getResponseCode());
        }
    }

    // Helper method to encode strings for URLs
    private static String encodeURIComponent(String value) {
        return java.net.URLEncoder.encode(value, StandardCharsets.UTF_8);
    }

    // Helper method to generate SHA512 hash for API services at Payu
    private static String generateSHA512HashAPI(String input) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-512");
        byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            hexString.append(String.format("%02x", b));
        }
        return hexString.toString();
    }
}
$END$

/*
 PayU API code for initiating initiate refund API
 Key, Salt and Environment must be configured.
 Below is the code for Initiate refund API, 
 here is the API documentation link for the same: https://docs.payu.in/reference/refund_transaction_api
*/

//Since the below code is a complete standalone java program, you may require to set up accordingly into your existing project
/* Uncomment the below imports if you are using this code in a standalone java program
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
*/

public class PayURefund {

    // Insert your key, salt, and environment in the below variables
        /*
         *To get your own key and salt values, login to payu.in and create a new merchant account
         *Here is the documentation link for the same:
            *Access test key and salt as per the document: https://docs.payu.in/docs/generate-test-merchant-key-and-salt
            *Access production key and salt as per the document: https://docs.payu.in/docs/generate-merchant-key-and-salt-on-payu-dashboard
            *Registering for a new merchant account is easy and takes less than 5 minutes.
            *You can also use the test key and salt provided in the documentation for testing purposes.
            *The test key and salt are not valid for production use.
            * API Documentation for this integration is available here: https://docs.payu.in/reference/refund_transaction_api
        */
    private static final String KEY = "$KEY$";
    private static final String SALT = "$SALT$";
    private static final String ENVIRONMENT = "$ENVIRONMENT$";

    public static void main(String[] args) {
        try {
            // Replace the dummy values with real payment details
            String payuid = "$PAYUID$";    // mihpayid provided in verify payment API response
            String tokenId = "$TOKEN_ID$"; // unique reconcilitation id for refund initiation from merchant
            String amount = "$AMOUNT$";   // amount to be refunded, partial refund is also possible, 
                                        // but the amount should be less than or equal to the original transaction amount

            // call the initiateRefund method to process the refund
            String response = initiateRefund(KEY, SALT, ENVIRONMENT, payuid, tokenId, amount);
            // Print the response from the server
            System.out.println("Response from PayU Refund API:");
            System.out.println(response); // Print the API response
        } catch (Exception e) {
            e.printStackTrace(); // Handle and log any errors
        }
    }

    /**
     * API Documentation for this integration is available here: https://docs.payu.in/reference/refund_transaction_api
     * This method initiates a refund for a given transaction ID.
     *
     * @param key This is the merchant key provided by PayU.
     * @param salt This is the merchant salt provided by PayU.
     * @param environment select the environment to use, either "sandbox" or "prod".
     * @param payuid put the payuid(mihpayid returned in verify payment API) for which you want to initiate the refund.
     * @param tokenId unique reconcilitation id for refund initiation from merchant.
     * @param amount put the amount to be refunded.
     * @return The response from the PayU server.
     */
    public static String initiateRefund(String key, String salt, String environment, String payuid, String tokenId, String amount) throws Exception {
        String apiURLV1;

        // Determine the API URL based on the environment
        if ("sandbox".equals(environment)) {
            apiURLV1 = "https://test.payu.in/merchant/postservice.php?form=2";
        } else if ("prod".equals(environment)) {
            apiURLV1 = "https://info.payu.in/merchant/postservice.php?form=2";
        } else {
            throw new IllegalArgumentException(
                "Invalid Environment passed. Expected values \"sandbox\" or \"prod\" but received: " + environment
            );
        }

        // Validate that the required fields are provided
        if (payuid == null || payuid.isEmpty()) {
            throw new IllegalArgumentException("payuid is missing");
        }

        String command = "cancel_refund_transaction"; // static value for refund transaction API

        // Compute the hash for the request
        String hashString = key + "|" + command + "|" + payuid + "|" + salt;
        String hash = generateSHA512HashAPI(hashString);

        // Prepare the form body with parameters
        String formBody = "key=" + encodeURIComponent(key) +
                          "&command=" + encodeURIComponent(command) +
                          "&var1=" + encodeURIComponent(payuid) +
                          "&var2=" + encodeURIComponent(tokenId) +
                          "&var3=" + encodeURIComponent(amount) +
                          "&hash=" + encodeURIComponent(hash);

        // Send the POST request
        HttpURLConnection conn = (HttpURLConnection) new URL(apiURLV1).openConnection();
        conn.setDoOutput(true);
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded"); // This is the content type for form data

        // Write the form data to the request body
        try (OutputStream os = conn.getOutputStream()) {
            os.write(formBody.getBytes(StandardCharsets.UTF_8));
        }

        // Read and return the API response
        if (conn.getResponseCode() == 200) {
            java.util.Scanner scanner = new java.util.Scanner(conn.getInputStream()).useDelimiter("\n");
            return scanner.hasNext() ? scanner.next() : "";
        } else {
            throw new Exception("HTTP Request failed with status code: " + conn.getResponseCode());
        }
    }

    // Helper method to generate SHA-512 hash
    private static String generateSHA512HashAPI(String input) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-512");
        byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            hexString.append(String.format("%02x", b));
        }
        return hexString.toString();
    }

    // Helper method to encode strings for URLs
    private static String encodeURIComponent(String value) {
        return java.net.URLEncoder.encode(value, StandardCharsets.UTF_8);
    }
}
$END$

