    }
    /**
     * API Documentation for this integration is available here: https://docs.payu.in/reference/check_action_status_api_with_payu_id
     * This method checks the refund status for a given transaction ID.
     *
     * @param key This is the merchant key provided by PayU.
     * @param salt This is the merchant salt provided by PayU.
     * @param environment select the environment to use, either "sandbox" or "prod".
     * @param payuid put the payuid(mihpayid returned in verify payment API) for which you want to check the refund status.
     * @return The response from the PayU server.
     */
    public static String checkRefundStatus(String key, String salt, String environment, String payuid) throws Exception {
        String apiURLV1;

        // Determine the API URL based on the environment
        if ("sandbox".equals(environment)) {
            apiURLV1 = "https://test.payu.in/merchant/postservice.php?form=2";
        } else if ("prod".equals(environment)) {
            apiURLV1 = "https://info.payu.in/merchant/postservice.php?form=2";
        } else {
            throw new IllegalArgumentException(
                "Invalid Environment passed. Expected values \"sandbox\" or \"prod\" but received: " + environment
            );
        }

        // Validate that the payuid is provided for checking the refund status
        if (payuid == null || payuid.isEmpty()) {
            throw new IllegalArgumentException("payuid is missing");
        }

        String command = "check_action_status"; // static value for check action status API 


        // Compute the hash for the request
        String hashString = key + "|" + command + "|" + payuid + "|" + salt;
        String hash = generateSHA512HashAPI(hashString);

        // Prepare the form body with parameters
        String formBody = "key=" + encodeURIComponent(key) +
                          "&command=" + encodeURIComponent(command) +
                          "&var1=" + encodeURIComponent(payuid) +
                          "&var2=" + encodeURIComponent("payuid") +
                          "&hash=" + encodeURIComponent(hash);

        // Send the POST request
        HttpURLConnection conn = (HttpURLConnection) new URL(apiURLV1).openConnection();
        conn.setDoOutput(true);
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");

        // Write the form data to the request body
        try (OutputStream os = conn.getOutputStream()) {
            os.write(formBody.getBytes(StandardCharsets.UTF_8));
        }

        // Read and return the API response
        if (conn.getResponseCode() == 200) {
            java.util.Scanner scanner = new java.util.Scanner(conn.getInputStream()).useDelimiter("\n");
            return scanner.hasNext() ? scanner.next() : "";
        } else {
            throw new Exception("HTTP Request failed with status code: " + conn.getResponseCode());
        }
    }

    // Helper method to generate SHA-512 hash
    private static String generateSHA512HashAPI(String input) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-512");
        byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            hexString.append(String.format("%02x", b));
        }
        return hexString.toString();
    }

    // Helper method to encode strings for URLs
    private static String encodeURIComponent(String value) {
        return java.net.URLEncoder.encode(value, StandardCharsets.UTF_8);
    }
}
